    "id": "VIIISIPEM-2021-GT03-381292",
    "title": "A MATEMÁTICA ESCOLAR E A AUTORIA DOCENTE NAS PROPOSTAS CURRICULARES BRASILEIRAS",
    "authors": [
      "Júlio César Augusto do Valle (Universidade de São Paulo)"
    ],
    "abstract": "O propósito deste texto consiste em apresentar uma proposta de pesquisa institucional e discutir os resultados parciais de seu desenvolvimento. A proposta se situa no contexto do projeto “Matemática nos currículos da Educação Básica, suas epistemologias e políticas”, que assume como objetivos mapear e analisar as propostas curriculares e/ou os currículos prescritos no Brasil, de 1929 a 2019, a fim de que seja possível compreender como a epistemologia da matemática subisidiou cada proposta, assim como suas implicações para o ensino de matemática em cada per íodo histórico. Busca -se, além disso, compreender e discutir os contextos de produção/formulação de cada proposta curricular em termos de evidenciar se houve participação/autoria docente em sua elaboração. Os resultados preliminares alcançados pela investi gação se inserem na busca por subsidiar um olhar crítico para o campo do currículo em sua interface com a Educação Matemática.",
