    "section": "",
    "type": "Trabalho",
    "pages": "",
    "language": "pt-BR",
    "officialUrl": "https://www.even3.com.br/Anais/VIIISIPEMvs2021/380169-POTENCIALIDADES-DA-REALIDADE-MISTA-PARA-SIMULACAO-DE-PRATICAS-DOCENTES--UM-CASO-NO-CURSO-DE-LICENCIATURA-EM-MATEM/",
