    "pages": "",
    "language": "pt-BR",
    "officialUrl": "https://www.even3.com.br/Anais/VIIISIPEMvs2021/381524-ANALISE-DE-ILUSTRACOES-DE-PROBLEMAS-DE-PROPORCAO-EM-LIVROS-DIDATICOS-DE-ANOS-INICIAIS/",
    "pdf": "https://static.even3.com/anais/381524.pdf",
