    "abstract": "O artigo analisa o Plano Experimental da Delegacia Regional de Ensino de Juiz de Fora, documento publicado em 1972 sob as referências do Movimento da Matemática Moderna (MMM), na perspectiva de identificar saberes profissionais dos professores primários para o ensino de Matemática. O objetivo é analisar as propostas para ensinar matemática desnaturalizan do-as em termos de reconfigurações de iniciativas já veiculadas em outros momentos, nomeadamente no período da Escola Nova; e aquelas identificadas com a Matemática Moderna mais propriamente. O uso do cotidiano e a ênfase no estudo da equivalência de fraçõ es são caracterizados como reconfigurações no contexto da MMM. Em relação às novas propostas, destacam -se o trabalho com generalização de propriedades e a noção de conjuntos para a construção do conceito de número.",
