    "abstract": "Este texto analisa as mudanças das ideias pedagógicas sobre o erro em matemática. Para tal, utiliza como referente teórico -metodológico categorias vindas da História Cultural. Assim, interessa analisar como foram construídas representações sobre o erro em matemática ao longo do tempo, tendo em vista um marco temporal que abrange desde a segunda metade do século XIX até aos dias atuais. As conclusões obtidas por meio da análise d e obras didáticas, textos utilizados na formação de professores, artigos de revistas pedagógicas dentre outros documentos, levam ao entendimento das mudanças do erro ligado ao cálculo exato até a valorização, em dias atuais, do cálculo aproximado.",
