    "id": "VIIISIPEM-2021-GT15-382053",
    "title": "PROBLEMAS DE GEOMETRIA E ARITMÉTICA: CONTRIBUIÇÕES DE JOSÉ RIBEIRO ESCOBAR (1923 - 1924)",
    "authors": [
      "ANDREIA FERNANDES DE SOUZA",
      "Joana Kelly Souza dos Santos",
      "Desconhecido4211"
    ],
    "abstract": "Para este texto foi traçado o objetivo de investigar qual a finalidade dos problemas em orientações para o professor que ensina matemática - Aritmética e Geometria - no curso primário de São Paulo nas propostas de José Ribeiro Escobar. Para isto, tomamos c omo fontes artigos deste autor presentes em exemplares das revistas pedagógicas Revista da Educação e Revista da Sociedade de Educação da década de 1920 que tratam sobre direcionamentos para o ensino de aritmética e geometria. Utilizamos como referenciais os estudos de Morais, Bertini e Valente (2021) para discutir sobre elementos da matemática do ensino e Bertini (2018) sobre os problemas. Foi identificado que a finalidade dos problemas varia conforme o conteúdo abordado. Há orientações que Escobar sugere os problemas no início da lição, como forma de introduzir o conteúdo, relacionando-o com materiais concretos, bem como propostas em que eles aparecem no final da lição, de modo a contribuir para verificar a aprendizagem, observando se o aluno foi capaz de abstrair determinado conteúdo. Nesse exercício, os problemas contribuem tanto para os processos indutivos ( observação, comparação, generalização) quanto para os processos dedutivos ( aplicação, verificação e comprovação).",
